import { onMounted, ref, watch } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';

// props

export default {
  __name: 'DeleteNetworkDialog',
  props: {
    modelValue: Boolean
  },
  emits: ['update:modelValue', 'refresh'],
  setup(__props, {
    expose: __expose,
    emit: __emit
  }) {
    __expose();
    const props = __props;
    const emit = __emit;

    // 控制显示
    const visible = ref(props.modelValue);
    watch(() => props.modelValue, val => visible.value = val);
    watch(visible, val => emit('update:modelValue', val));

    // 表单数据
    const form = ref({
      networkName: ''
    });

    // 获取网络名列表
    const networkNames = ref([]);
    const fetchNetworkNames = async () => {
      try {
        const res = await axios.get('http://localhost:8081/network/list');
        networkNames.value = Object.keys(res.data);
      } catch (err) {
        ElMessage.error('获取网络列表失败');
      }
    };

    // 删除网络
    const submitDelete = async () => {
      if (!form.value.networkName) {
        ElMessage.warning('请选择网络名称');
        return;
      }
      try {
        await axios.delete(`http://localhost:8081/network/delete/${form.value.networkName}`);
        ElMessage.success('删除成功');
        emit('refresh'); // 通知父组件刷新列表
        handleClose();
      } catch (err) {
        ElMessage.error('删除失败');
      }
    };

    // 关闭弹窗
    const handleClose = () => {
      visible.value = false;
      form.value.networkName = '';
    };
    onMounted(() => {
      fetchNetworkNames();
    });
    const __returned__ = {
      props,
      emit,
      visible,
      form,
      networkNames,
      fetchNetworkNames,
      submitDelete,
      handleClose,
      onMounted,
      ref,
      watch,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
